using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using StudentAccommodationSystem.Models; using StudentAccommodationSystem.ViewModels; using StudentAccommodationSystem.Data;
namespace StudentAccommodationSystem.Controllers;
public class AccountController(UserManager<ApplicationUser> users,SignInManager<ApplicationUser> signIn,ApplicationDbContext db) : Controller
{
 public IActionResult Login(string? returnUrl=null)=>View(new LoginViewModel());
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel m,string? returnUrl=null){if(!ModelState.IsValid)return View(m);var u=await users.FindByEmailAsync(m.Email);if(u==null||!u.IsActive){ModelState.AddModelError("","Invalid account.");return View(m);}var r=await signIn.PasswordSignInAsync(u,m.Password,m.RememberMe,false);if(!r.Succeeded){ModelState.AddModelError("","Invalid login attempt.");return View(m);}if(!string.IsNullOrWhiteSpace(returnUrl)&&Url.IsLocalUrl(returnUrl))return Redirect(returnUrl);if(await users.IsInRoleAsync(u,"Administrator"))return RedirectToAction("Index","Admin");if(await users.IsInRoleAsync(u,"Owner"))return RedirectToAction("Index","Owner");if(await users.IsInRoleAsync(u,"Student"))return RedirectToAction("Index","Student");await signIn.SignOutAsync();ModelState.AddModelError("", "Your account has no supported dashboard role. Please contact an administrator.");return View(m);}
 public IActionResult Register()=>View(new RegisterViewModel());
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(RegisterViewModel m){if(!ModelState.IsValid)return View(m);if(m.Role!="Student" && m.Role!="Owner"){ModelState.AddModelError(nameof(m.Role),"Please select Student or Owner.");return View(m);}var u=new ApplicationUser{UserName=m.Email,Email=m.Email,FullName=m.FullName,EmailConfirmed=true};var r=await users.CreateAsync(u,m.Password);if(!r.Succeeded){foreach(var e in r.Errors)ModelState.AddModelError("",e.Description);return View(m);}await users.AddToRoleAsync(u,m.Role);if(m.Role=="Student") db.StudentProfiles.Add(new StudentProfile{UserId=u.Id}); else if(m.Role=="Owner") db.OwnerProfiles.Add(new OwnerProfile{UserId=u.Id}); await db.SaveChangesAsync(); return RedirectToAction(nameof(Login));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await signIn.SignOutAsync();return RedirectToAction("Index","Home");}
}
